import json

# Input data
n_slots = 9  # number of slots on each template
n_templates = 2  # number of templates
n_var = 7  # number of variations
demand = [250, 255, 260, 500, 500, 800, 1100]  # demand for each variation

# Create the CP-SAT model
model = cp_model.CpModel()

# Upper bounds for production and intermediate products
max_demand = max(demand)
max_prod = max_demand
max_y = max_prod * n_slots  # upper bound for production[t] * count[t][j]

# Decision variables

# x[t, s, j] = 1 if on template t, slot s is assigned variation j
x = {}
for t in range(n_templates):
    for s in range(n_slots):
        for j in range(n_var):
            x[(t, s, j)] = model.NewBoolVar(f'x_t{t}_s{s}_j{j}')

# count[t, j] = number of slots on template t assigned to variation j
count = {}
for t in range(n_templates):
    for j in range(n_var):
        count[(t, j)] = model.NewIntVar(0, n_slots, f'count_t{t}_j{j}')

# layout[t, s] = variation index assigned to slot s on template t
layout = {}
for t in range(n_templates):
    for s in range(n_slots):
        layout[(t, s)] = model.NewIntVar(0, n_var - 1, f'layout_t{t}_s{s}')

# production[t] = number of sheets to print for template t
production = {}
for t in range(n_templates):
    production[t] = model.NewIntVar(0, max_prod, f'production_t{t}')

# y[t, j] = production[t] * count[t, j]
y = {}
for t in range(n_templates):
    for j in range(n_var):
        y[(t, j)] = model.NewIntVar(0, max_y, f'y_t{t}_j{j}')

# Constraints

# Each slot on each template must be assigned exactly one variation
for t in range(n_templates):
    for s in range(n_slots):
        model.Add(sum(x[(t, s, j)] for j in range(n_var)) == 1)

# Link count[t, j] to x: count occurrences of variation j on template t
for t in range(n_templates):
    for j in range(n_var):
        model.Add(sum(x[(t, s, j)] for s in range(n_slots)) == count[(t, j)])

# Link layout[t, s] to x: layout index equals the chosen j
for t in range(n_templates):
    for s in range(n_slots):
        model.Add(sum(j * x[(t, s, j)] for j in range(n_var)) == layout[(t, s)])

# Define y[t, j] = production[t] * count[t, j]
for t in range(n_templates):
    for j in range(n_var):
        model.AddMultiplicationEquality(y[(t, j)], [production[t], count[(t, j)]])

# Demand satisfaction: sum over templates of y[t, j] >= demand[j]
for j in range(n_var):
    model.Add(sum(y[(t, j)] for t in range(n_templates)) >= demand[j])

# Objective: minimize total number of printed sheets
model.Minimize(sum(production[t] for t in range(n_templates)))

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

# Print the solution in JSON format
if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    solution = {
        'production': [solver.Value(production[t]) for t in range(n_templates)],
        'layout': [
            [solver.Value(layout[(t, s)]) for s in range(n_slots)]
            for t in range(n_templates)
        ]
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
