from ortools.sat.python import cp_model
import json

# Input data
n_boats = 5  # Number of boats
n_periods = 4  # Number of periods
capacity = [6, 8, 12, 12, 12]  # Capacities of the boats
crew_size = [2, 2, 2, 2, 4]  # Crew sizes of the boats

# Model definition
model = cp_model.CpModel()

# Decision Variables
# is_host[b] = 1 if boat b is a host
is_host = [model.NewBoolVar(f"is_host[{b}]") for b in range(n_boats)]

# x[p][i][h] = 1 if in period p, boat i visits host boat h
x = {}
for p in range(n_periods):
    for i in range(n_boats):
        for h in range(n_boats):
            x[p, i, h] = model.NewBoolVar(f"x[{p},{i},{h}]")

# meet[p,i,j,h] = 1 if in period p boats i and j both visit host h
meet = {}
for p in range(n_periods):
    for i in range(n_boats):
        for j in range(i + 1, n_boats):
            for h in range(n_boats):
                meet[p, i, j, h] = model.NewBoolVar(f"meet[{p},{i},{j},{h}]")

# Constraints

# 1. A boat i visits exactly one host if it's not a host, none if it is a host
for p in range(n_periods):
    for i in range(n_boats):
        model.Add(sum(x[p, i, h] for h in range(n_boats)) == 1 - is_host[i])

# 2. You can only visit host boats
for p in range(n_periods):
    for i in range(n_boats):
        for h in range(n_boats):
            model.Add(x[p, i, h] <= is_host[h])

# 3. Capacity constraints on each host boat each period
for p in range(n_periods):
    for h in range(n_boats):
        model.Add(
            crew_size[h] + sum(crew_size[i] * x[p, i, h] for i in range(n_boats))
            <= capacity[h]
        )

# 4. No guest boat revisits the same host
for i in range(n_boats):
    for h in range(n_boats):
        model.Add(sum(x[p, i, h] for p in range(n_periods)) <= 1)

# 5. Define meet variables and limit meetings to at most once per pair
for p in range(n_periods):
    for i in range(n_boats):
        for j in range(i + 1, n_boats):
            # Build meet indicator: meet = 1 iff both x[p,i,h] and x[p,j,h] = 1
            for h in range(n_boats):
                model.AddBoolAnd([x[p, i, h], x[p, j, h]]).OnlyEnforceIf(meet[p, i, j, h])
                model.AddBoolOr([x[p, i, h].Not(), x[p, j, h].Not()]).OnlyEnforceIf(meet[p, i, j, h].Not())
            # Sum of all meet[p,i,j,h] over hosts h is the meeting at period p
            model.Add(sum(meet[p, i, j, h] for h in range(n_boats)) <= 1)
# And across all periods they meet at most once
for i in range(n_boats):
    for j in range(i + 1, n_boats):
        model.Add(sum(meet[p, i, j, h] for p in range(n_periods) for h in range(n_boats)) <= 1)

# Objective: Minimize the number of hosts
model.Minimize(sum(is_host))

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

# Print solution
if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    # Build visits schedule: for each period p and boat i, the host it visits, or -1 if it's a host
    visits = []
    for p in range(n_periods):
        row = []
        for i in range(n_boats):
            if solver.Value(is_host[i]) == 1:
                row.append(-1)
            else:
                # find the host h with x[p,i,h] = 1
                for h in range(n_boats):
                    if solver.Value(x[p, i, h]) == 1:
                        row.append(h)
                        break
        visits.append(row)

    solution = {
        "visits": visits,
        "is_host": [solver.Value(is_host[b]) for b in range(n_boats)]
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
