# Input data
n_teams = 8  # Number of teams
n_weeks = n_teams - 1
n_periods = n_teams // 2

# Model definition
model = cp_model.CpModel()

# Decision Variables
# home[w][p] is the home team playing in week w, period p
# away[w][p] is the away team playing in week w, period p
home = []
away = []
for w in range(n_weeks):
    home.append([model.NewIntVar(0, n_teams - 1, f"home_w{w}_p{p}") for p in range(n_periods)])
    away.append([model.NewIntVar(0, n_teams - 1, f"away_w{w}_p{p}") for p in range(n_periods)])

# Channeling: home_is[w][p][i] is true if home[w][p] == i
#             away_is[w][p][i] is true if away[w][p] == i
home_is = {}
away_is = {}
for w in range(n_weeks):
    for p in range(n_periods):
        for i in range(n_teams):
            b_h = model.NewBoolVar(f"home_is_w{w}_p{p}_t{i}")
            b_a = model.NewBoolVar(f"away_is_w{w}_p{p}_t{i}")
            home_is[(w, p, i)] = b_h
            away_is[(w, p, i)] = b_a
            # Link home variable and boolean
            model.Add(home[w][p] == i).OnlyEnforceIf(b_h)
